def widest_ramp(prices):
    stack = []  # days lower than every earlier day
    for i, p in enumerate(prices):
        if not stack or p < prices[stack[-1]]:
            stack.append(i)
    best = 0
    for j in range(len(prices) - 1, -1, -1):
        while stack and prices[stack[-1]] <= prices[j]:
            best = max(best, j - stack.pop())
    return best

